static void write_segment(Elf64_Phdr phdr, FILE * fp,
                          FILE * img, int *nbytes)
{
	/* only write loadable segments with non-zero memory size */
	if (phdr.p_type != PT_LOAD || phdr.p_memsz == 0) {
		return;
	}

	/* 512 bytes align */
	int bytes;
	if(phdr.p_memsz % 512 == 0) {
		bytes = phdr.p_memsz;
	}
	else {
		bytes = phdr.p_memsz + (512 - phdr.p_memsz % 512);
	}

	/* copy the segment in fixed-size (one sector) chunks,
	 * zero-padding the final partial sector */
	char segment_file[512];
	int remaining = phdr.p_memsz;
	int filesz = phdr.p_filesz;

	fseek(fp, phdr.p_offset, SEEK_SET);
	while (remaining > 0) {
		int chunk = remaining > 512 ? 512 : remaining;
		int from_file = filesz > chunk ? chunk : filesz;

		memset(segment_file, 0, sizeof(segment_file));
		if (from_file > 0) {
			fread(segment_file, from_file, 1, fp);
		}
		fwrite(segment_file, chunk, 1, img);

		remaining -= chunk;
		filesz -= from_file;
	}

	(*nbytes) += bytes;

	return;
}

static void write_os_size(int nbytes, FILE * img)
{
	long OS_SIZE_LOC = 508;
	nbytes = nbytes / 512 - 1;
	fseek(img, OS_SIZE_LOC, SEEK_SET);
	fwrite(&nbytes, 2, 1, img);
	printf("os_size: %d sectors\n", nbytes);
	return;
}

